CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE gene(gene_id integer PRIMARY KEY, gene_symbol text NOT NULL UNIQUE, description text NOT NULL);
INSERT INTO gene VALUES (672,'BRCA1','BRCA1 DNA repair associated'),(675,'BRCA2','BRCA2 DNA repair associated'),(7157,'TP53','Tumor protein p53');
CREATE TABLE release(release_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, release_date date NOT NULL UNIQUE, label text NOT NULL UNIQUE, manifest_sha256 text NOT NULL, provenance text NOT NULL CHECK(provenance IN ('clinvar_archive','synthetic_fixture')), imported_at timestamptz NOT NULL DEFAULT now(), stats jsonb NOT NULL DEFAULT '{}');
CREATE TABLE release_artifact(release_id integer REFERENCES release, kind text, url text, sha256 text, bytes bigint, PRIMARY KEY(release_id,kind));
CREATE TABLE submitter(submitter_id text PRIMARY KEY, submitter_name text NOT NULL, organization_type text);
CREATE TABLE classification_term(class_code text PRIMARY KEY, label text NOT NULL);
INSERT INTO classification_term VALUES ('P','Pathogenic / likely pathogenic'),('V','Uncertain significance'),('B','Benign / likely benign'),('C','Conflicting classifications'),('O','Other / not classified');
CREATE VIEW class_conflict_rule AS SELECT class_code,(class_code='C') AS is_conflicting FROM classification_term;
CREATE TABLE review_status(status_code text PRIMARY KEY, status_label text NOT NULL, review_stars integer NOT NULL CHECK(review_stars BETWEEN 0 AND 4));
CREATE TABLE variant(variant_id bigint PRIMARY KEY, gene_id integer NOT NULL REFERENCES gene, variant_name text NOT NULL, variant_type text, chromosome text, position bigint, ref text, alt text);
CREATE TABLE clinical_assertion(scv_accession text PRIMARY KEY, variant_id bigint NOT NULL REFERENCES variant, submitter_id text NOT NULL REFERENCES submitter, first_release_id integer NOT NULL REFERENCES release);
CREATE TABLE assertion_version(scv_accession text NOT NULL REFERENCES clinical_assertion, version_no integer NOT NULL, class_code text NOT NULL REFERENCES classification_term, status_code text NOT NULL REFERENCES review_status, date_evaluated date, first_release_id integer NOT NULL REFERENCES release, last_release_id integer REFERENCES release, content_hash text NOT NULL, raw jsonb NOT NULL, PRIMARY KEY(scv_accession,version_no), CHECK(last_release_id IS NULL OR last_release_id>first_release_id), EXCLUDE USING gist(scv_accession WITH =, int4range(first_release_id,last_release_id,'[)') WITH &&));
CREATE INDEX assertion_variant_idx ON clinical_assertion(variant_id);
CREATE INDEX assertion_span_idx ON assertion_version USING gist(int4range(first_release_id,last_release_id,'[)'));
CREATE TABLE variant_state(variant_id bigint REFERENCES variant, release_id integer REFERENCES release, aggregate_class text REFERENCES classification_term, review_stars integer NOT NULL CHECK(review_stars BETWEEN 0 AND 4), submitter_count integer NOT NULL CHECK(submitter_count>=0), assertion_count integer NOT NULL CHECK(assertion_count>=0), n_p integer NOT NULL, n_vus integer NOT NULL, n_b integer NOT NULL, PRIMARY KEY(variant_id,release_id));
CREATE TABLE validation_result(variant_id bigint REFERENCES variant, release_id integer REFERENCES release, official_class text, calculated_class text, matches boolean, PRIMARY KEY(variant_id,release_id));
CREATE TABLE change_event(event_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, variant_id bigint NOT NULL, from_release_id integer NOT NULL, to_release_id integer NOT NULL, change_type text NOT NULL CHECK(change_type IN ('semantic','review_only')), UNIQUE(variant_id,from_release_id,to_release_id), CHECK(to_release_id>from_release_id), FOREIGN KEY(variant_id,from_release_id) REFERENCES variant_state, FOREIGN KEY(variant_id,to_release_id) REFERENCES variant_state);
CREATE VIEW event_details AS SELECT e.*,f.aggregate_class AS from_class,t.aggregate_class AS to_class FROM change_event e JOIN variant_state f ON(f.variant_id=e.variant_id AND f.release_id=e.from_release_id) JOIN variant_state t ON(t.variant_id=e.variant_id AND t.release_id=e.to_release_id);
CREATE TABLE model_version(model_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, model_name text NOT NULL, feature_set text NOT NULL, origin_release_id integer NOT NULL REFERENCES release, horizon integer NOT NULL CHECK(horizon IN (1,3)), trained_on_release integer REFERENCES release, run_key text NOT NULL UNIQUE, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE drift_prediction(prediction_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, model_id bigint NOT NULL REFERENCES model_version, variant_id bigint NOT NULL REFERENCES variant, origin_release_id integer NOT NULL REFERENCES release, horizon integer NOT NULL CHECK(horizon IN (1,3)), score double precision NOT NULL CHECK(score BETWEEN 0 AND 1), audit_rank integer NOT NULL CHECK(audit_rank>0), UNIQUE(model_id,variant_id,origin_release_id,horizon), UNIQUE(model_id,audit_rank));
CREATE TABLE prediction_outcome(variant_id bigint REFERENCES variant, origin_release_id integer REFERENCES release, horizon integer CHECK(horizon IN (1,3)), target_release_id integer REFERENCES release, realized_label boolean NOT NULL, PRIMARY KEY(variant_id,origin_release_id,horizon));
CREATE VIEW prediction_results AS SELECT p.*,o.realized_label,o.target_release_id FROM drift_prediction p LEFT JOIN prediction_outcome o USING(variant_id,origin_release_id,horizon);
CREATE TABLE outbox_event(event_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, event_key text NOT NULL UNIQUE, topic text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), delivered_mongo boolean NOT NULL DEFAULT false, delivered_neo4j boolean NOT NULL DEFAULT false, attempts integer NOT NULL DEFAULT 0, last_error text);
CREATE TABLE benchmark_result(model_id bigint PRIMARY KEY REFERENCES model_version, metrics jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feature_materialization(variant_id bigint REFERENCES variant, origin_release_id integer REFERENCES release, feature_set text, features jsonb NOT NULL, lineage_max_release integer NOT NULL, feature_hash text NOT NULL, PRIMARY KEY(variant_id,origin_release_id,feature_set), CHECK(lineage_max_release<=origin_release_id));
CREATE INDEX states_release_idx ON variant_state(release_id);
CREATE INDEX event_variant_idx ON change_event(variant_id,to_release_id);
CREATE INDEX outbox_pending_idx ON outbox_event(event_id) WHERE NOT delivered_mongo OR NOT delivered_neo4j;
